"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { ChatForm } from "@/components/chat-form";
import { claimFirstPrompt } from "../actions";
import { ChatMessages, RESUMED_RUN, applyChatEvent, type ChatItem, type PendingExchange } from "@/components/chat-messages";
import { usePolling } from "@/lib/use-polling";
import { SavedVersion, type HomeVersions } from "./saved-version";
import type { ChatAnswer, ChatStreamEvent } from "@/lib/ai/use-chat-request";
import type { ChatAttachment } from "@/lib/ai/chat-attachments";

type Loaded = { messages: ChatItem[]; messagesCursor: string | null; running?: string | null };
const SEND_EVENT = "moneo-artifact-send";

export function SendButton({ prompt, idle, label, sending }: { prompt: string; idle: string; label: string; sending: string }) {
  const [sent, setSent] = useState(false);
  return <span className="block space-y-3 text-sm text-muted-foreground">
    <span role="status" className="block">{sent ? sending : idle}</span>
    {!sent && <button type="button" onClick={() => { setSent(true); window.dispatchEvent(new CustomEvent(SEND_EVENT, { detail: prompt })); }}
      className="min-h-10 rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground hover:opacity-90">{label}</button>}
  </span>;
}

export function ArtifactChat({ conversationId, initial, messagesCursor, running: initialRunning, artifactId, artifact, home }: { conversationId: string; initial: ChatItem[]; messagesCursor: string | null; running: string | null; artifactId?: string; artifact: string; home: HomeVersions }) {
  const router = useRouter();
  const [messages, setMessages] = useState(initial);
  const [older, setOlder] = useState(messagesCursor);
  const [loadingOlder, setLoadingOlder] = useState(false);
  const [historyError, setHistoryError] = useState("");
  const prepended = useRef(false);
  const [running, setRunning] = useState(initialRunning);
  const [pending, setPending] = useState<PendingExchange | null>(null);
  const live = useRef<PendingExchange | null>(null);
  const scroll = useRef<HTMLDivElement>(null);
  useEffect(() => { if (prepended.current) { prepended.current = false; return; } if (scroll.current) scroll.current.scrollTop = scroll.current.scrollHeight; }, [messages.length, pending]);
  const [request, setRequest] = useState<string>();
  const [claimFailed, setClaimFailed] = useState(false);
  const [claimAttempt, setClaimAttempt] = useState(0);
  useEffect(() => {
    const listener = (event: Event) => setRequest((event as CustomEvent<string>).detail);
    window.addEventListener(SEND_EVENT, listener);
    return () => window.removeEventListener(SEND_EVENT, listener);
  }, []);
  useEffect(() => {
    if (!artifactId) return;
    claimFirstPrompt(artifactId).then(prompt => { setClaimFailed(false); if (prompt) setRequest(prompt); else router.refresh(); }, () => setClaimFailed(true));
  }, [artifactId, claimAttempt, router]);

  const resuming = running && !pending;
  const [unreachable, setUnreachable] = useState(false);
  usePolling(signal => fetch(`/api/conversations/${conversationId}`, { cache: "no-store", signal }).then(response => { if (!response.ok) throw new Error(); return response.json() as Promise<Loaded>; }).then(data => {
    setUnreachable(false);
    if (data.running) return;
    setMessages(current => [...current.filter(message => !data.messages.some(item => item.id === message.id)), ...data.messages]); setRunning(null); router.refresh();
  }).catch(() => { if (!signal.aborted) setUnreachable(true); }), 3000, !!resuming);

  async function loadOlder() {
    if (!older || loadingOlder) return;
    setLoadingOlder(true); setHistoryError("");
    try {
      const response = await fetch(`/api/conversations/${conversationId}?${new URLSearchParams({ messagesBefore: older })}`, { cache: "no-store" });
      if (!response.ok) throw new Error("Could not load older messages. Try again.");
      const data = await response.json() as Loaded;
      prepended.current = true;
      setMessages(current => [...data.messages.filter(message => !current.some(item => item.id === message.id)), ...current]);
      setOlder(data.messagesCursor);
    } catch (cause) { setHistoryError(cause instanceof Error ? cause.message : "Could not load older messages. Try again."); }
    finally { setLoadingOlder(false); }
  }

  function onStart(_id: string, question: string, attachments: ChatAttachment[], spoken: boolean, regenerating = false) { live.current = { question, attachments, tools: [], spoken, regenerating }; setPending(live.current); }
  function onEvent(_id: string, event: ChatStreamEvent) {
    if (!live.current) return;
    const before = live.current;
    live.current = applyChatEvent(before, event);
    setPending(live.current);
    if (event.type === "tool" && event.state === "done" && ["write_page", "card_preset", "write_card", "remove_card"].includes(event.name ?? "")) router.refresh();
  }
  function onDone(_id: string, question: string, result: ChatAnswer | null, attachments: ChatAttachment[]) {
    const finished = live.current;
    live.current = null; setPending(null); setRequest(undefined);
    if (!result) return;
    const now = new Date().toISOString();
    setMessages(current => [...current,
      ...(result.regenerates ? [] : [{ id: `local-${crypto.randomUUID()}`, role: "user" as const, content: question.trim(), created_at: now, attachments, spoken: finished?.spoken }]),
      ...(finished?.steers ?? []).map(content => ({ id: `local-${crypto.randomUUID()}`, role: "user" as const, content, created_at: now })),
      { id: `local-${crypto.randomUUID()}`, role: "assistant", content: result.answer, created_at: now, answer_of: result.regenerates ?? result.requestId, tools: finished?.tools.length ? finished.tools : result.toolsUsed, plan: finished?.plan }]);
    router.refresh();
  }

  return <div className="flex min-h-0 flex-1 flex-col">
    <div ref={scroll} aria-label="Artifact chat messages" className="relative min-h-0 flex-1 overflow-y-auto pr-1">
      {older && <button type="button" disabled={loadingOlder} onClick={() => void loadOlder()} className="mb-4 min-h-9 rounded-lg border border-border px-3 text-xs text-muted-foreground disabled:opacity-50">{loadingOlder ? "Loading older messages…" : "Older messages"}</button>}
      {historyError && <p role="alert" className="mb-3 text-sm text-danger">{historyError}</p>}
      {messages.length || pending || resuming ? <ChatMessages compact messages={messages} pending={pending ?? (resuming ? RESUMED_RUN : undefined)} toolResult={(step, key) => <SavedVersion key={key} step={step} artifactId={artifact} home={home} />} />
        : <p className="text-sm text-muted-foreground">Describe what to build. Ask for a Home card any time, e.g. “add this to Home as a small card”.</p>}
    </div>
    {unreachable && resuming && <p role="alert" className="text-xs text-warning">Could not check on this build. It may still be running. Moneo keeps trying.</p>}
    {claimFailed && <p role="alert" className="text-sm text-danger">Could not start your request. <button type="button" onClick={() => setClaimAttempt(count => count + 1)} className="underline">Try again</button></p>}
    <ChatForm conversationId={conversationId} selectionKey={`moneo-artifact-${conversationId}`} autoSend={request} placeholder="Change the page or a card…" onStart={onStart} onEvent={onEvent} onDone={onDone} />
  </div>;
}
"use client";

import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { selectConversation } from "@/lib/ai/selected-conversation";
import { useChatRequest, type ChatAnswer, type ChatStreamEvent } from "@/lib/ai/use-chat-request";
import { useChatQueue } from "@/lib/ai/use-chat-queue";
import { useChatAttachments } from "@/lib/ai/use-chat-attachments";
import { ATTACHMENT_ONLY_MESSAGE, type ChatAttachment } from "@/lib/ai/chat-attachments";
import { ChatComposer, withSpoken } from "@/components/chat-composer";
import { VOICE_CONTEXT } from "@/lib/ai/voice-context";
import { ChatQueue } from "@/components/chat-queue";
import { DRAFT_EVENT } from "@/components/chat-messages";
import { RESEND_EVENT, type Resend } from "@/components/message-actions";

const draftIsNotKeptWhenStorageIsBlocked = () => undefined;
const suggestions = ["What changed in my spending last month?", "Where did most of my money go this month?", "Find my largest transactions", "Create a spending chart"];

export type ChatFormEvents = {
  onStart?: (conversationId: string, question: string, attachments: ChatAttachment[], spoken: boolean, regenerating?: boolean) => void;
  onEvent?: (conversationId: string, event: ChatStreamEvent) => void;
  onDone?: (conversationId: string, question: string, result: ChatAnswer | null, attachments: ChatAttachment[]) => void;
};

export function ChatForm({ conversationId, selectionKey, empty = false, scope, placeholder = "Ask anything about your money", autoSend, onStart, onEvent, onDone }: { conversationId: string; selectionKey: string; isNewConversation?: boolean; empty?: boolean; scope?: React.ReactNode; placeholder?: string; autoSend?: string } & ChatFormEvents) {
  const [message, setMessage] = useState("");
  const draftKey = `moneo-chat-draft:${conversationId}`;
  const draftLoaded = useRef(false);
  useEffect(() => {
    try {
      if (draftLoaded.current) { if (message) sessionStorage.setItem(draftKey, message); else sessionStorage.removeItem(draftKey); return; }
      draftLoaded.current = true;
      const saved = sessionStorage.getItem(draftKey);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      if (saved) setMessage(current => current || saved);
    } catch { draftIsNotKeptWhenStorageIsBlocked(); }
  }, [message, draftKey]);
  const chat = useChatRequest();
  const files = useChatAttachments();
  const { send, cancel, busy, error, status } = chat;
  useEffect(() => {
    const draft = (event: Event) => { const detail = (event as CustomEvent<{ prompt?: string; compact: boolean }>).detail; if (!detail.compact && detail.prompt) { setMessage(detail.prompt); document.getElementById("question")?.focus(); } };
    window.addEventListener(DRAFT_EVENT, draft);
    return () => window.removeEventListener(DRAFT_EVENT, draft);
  }, []);

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!message.trim() && !files.ready.length) return;
    if (busy) { if (files.items.length) return; enqueue(message); setMessage(""); return; }
    void sendMessage(message, false, files.ready);
  }

  function sendSpoken(text: string) {
    const typed = withSpoken(message, text);
    if (files.uploading || files.items.some(item => item.error) || (busy && files.items.length)) { setMessage(typed); document.getElementById("question")?.focus(); return; }
    if (busy) { enqueue(typed); setMessage(""); return; }
    void sendMessage(typed, false, files.ready, true);
  }

  async function sendMessage(typed: string, queued = false, attachments: ChatAttachment[] = [], spoken = false, regenerates?: string) {
    if (busy) return;
