import { expect, test } from "@playwright/test";
import postgres from "postgres";
import { randomUUID } from "node:crypto";
import { e2eStorageStatePath, gatedSkipReason, hasSupabaseEnv } from "./fixtures";

const state = e2eStorageStatePath();
if (state) test.use({ storageState: state });
test.skip(!hasSupabaseEnv() || !state || !process.env.SUPABASE_DB_URL || !process.env.E2E_USER_EMAIL, gatedSkipReason());

test("coming back to a chat still answering shows it working, then the saved answer", async ({ page }) => {
  test.setTimeout(60_000);
  const db = postgres(process.env.SUPABASE_DB_URL!, { max: 1, onnotice: () => {} });
  const [{ id: workspaceId }] = await db`select w.id from public.workspaces w join auth.users u on u.id = w.owner_id where u.email = ${process.env.E2E_USER_EMAIL!}`;
  const conversationId = randomUUID(), requestId = randomUUID();
  const question = `Background QA ${requestId.slice(0, 8)}`;
  try {
    await db`insert into public.conversations (id, workspace_id, title) values (${conversationId}, ${workspaceId}, ${question})`;
    await db`insert into public.chat_requests (id, workspace_id, conversation_id, message) values (${requestId}, ${workspaceId}, ${conversationId}, ${question})`;
    await db`insert into public.messages (workspace_id, conversation_id, role, content, context, request_id) values (${workspaceId}, ${conversationId}, 'user', ${question}, '{}', ${requestId})`;

    await page.goto(`/ai?conversation=${conversationId}`);
    const main = page.locator("main");
    await expect(main.getByText(question, { exact: true }).last()).toBeVisible();
    await expect(main.getByRole("status").filter({ hasText: "Thinking…" })).toBeVisible();

    await db`insert into public.messages (workspace_id, conversation_id, role, content, reply_to) values (${workspaceId}, ${conversationId}, 'assistant', 'Finished while you were away', ${requestId})`;
    await db`update public.chat_requests set status = 'completed', answer = 'Finished while you were away', updated_at = now() where id = ${requestId}`;
    await expect(main.getByText("Finished while you were away")).toBeVisible({ timeout: 15_000 });
    await expect(main.getByRole("status").filter({ hasText: "Thinking…" })).toHaveCount(0);
  } finally {
    await db`delete from public.messages where conversation_id = ${conversationId}`;
    await db`delete from public.chat_requests where id = ${requestId}`;
    await db`delete from public.conversations where id = ${conversationId}`;
    await db.end();
  }
});
25:- `*.smoke.spec.ts` and `*.mocked.spec.ts` stub or skip the backend. Against a configured backend they still need the QA session, like every spec.
26:- `*.gated.spec.ts` need the backend. Most use the QA session; others create disposable users with the service key, sign them in by session cookie, and remove them in `finally`. If interrupted, their IDs are left in ignored `.qa/` files for cleanup.
27:- `*.provider.spec.ts` call the real AI model, so they cost money. They run only with `E2E_REAL_AI=1`; `npm run test:e2e` leaves them out.
32:The `browser` job in `.github/workflows/ci.yml` runs on every pull request. It starts its own disposable `moneo-qa` backend on the runner (`npm run setup -- --qa`, with the same retry as the `database` job), creates the QA user (`npm run qa:auth`), builds this checkout and serves it on port 3100 against `.env.qa` with AI, bank and Scalable access off (`E2E_PRODUCTION_BUILD=1`, see `scripts/qa-server.mjs`), then runs one worker with one retry over a bounded set of specs: `net-worth.gated.spec.ts` (accepting a cash-machine proposal card once even when double-clicked, dismissing one without applying it, and checking both after a reload; proposal cards have no undo, so none is tested) and `import-journey.mocked.spec.ts`. A failure fails the job and uploads `test-results/` (a trace and screenshot per failed test) as the `browser-failures` artifact for 7 days. The runner and its backend are discarded afterwards, and the specs only create synthetic rows, so the artifact holds no owner data or credentials. The specs refuse any server that would sign tests in as the owner (`e2e/global-setup.ts`).
37:E2E_PRODUCTION_BUILD=1 npx playwright test --workers=1 e2e/net-worth.gated.spec.ts e2e/import-journey.mocked.spec.ts
49:`scalable-trading.provider.spec.ts` drives chat against a local stand-in for Scalable's MCP server (`e2e/mocks/scalable-mcp.mjs`, made-up data) with the real AI model. Start `npm run qa:server` with `SCALABLE_MCP_ORIGIN=http://127.0.0.1:3043` (and the AI key in `.env.qa`) and run the spec with the same variable and `E2E_REAL_AI=1`; the spec starts the stand-in, adds a Scalable connection to the QA workspace and removes it afterwards. It checks that an order is previewed on a card and sent only when the card is tapped, once, and that read-only access is told it can't trade.

